import React,{useMemo,useState} from 'react';
import {AlertTriangle,Wrench} from 'lucide-react';
import {useRuntime} from '../runtime/RuntimeProvider';
import {buttonClass,fieldClass,recordOf,recordsOf,shortDate} from './records';

// SERVOS_PATCH_06_HOUSEKEEPING
const FLOW:{[key:string]:string}={DIRTY:'CLEANING',CLEANING:'INSPECTION',INSPECTION:'CLEAN'};
const label:{[key:string]:string}={DIRTY:'Start cleaning',CLEANING:'Send to inspection',INSPECTION:'Pass inspection'};
export function NativeHousekeepingView(){
 const runtime=useRuntime();const s=runtime.snapshot!;const rooms=recordsOf(s,'rooms'),types=recordsOf(s,'roomTypes'),blocks=recordsOf(s,'roomBlocks'),reservations=recordsOf(s,'roomReservations');
 const [query,setQuery]=useState('');const [message,setMessage]=useState('');
 const visible=useMemo(()=>rooms.filter(r=>`${r.number} ${r.floor||''} ${r.wing||''}`.toLowerCase().includes(query.toLowerCase())),[rooms,query]);
 const command=async(op:string,payload:any,version?:number)=>{setMessage('');try{await runtime.command(op,payload,version);setMessage('Housekeeping action committed.')}catch(e){setMessage(String(e))}};
 const transition=async(room:any,state:string)=>{const rec=recordOf(s,'rooms',room.id);if(rec)await command('room.housekeeping',{id:room.id,state},rec.version)};
 const condition=async(room:any)=>{const rec=recordOf(s,'rooms',room.id);if(!rec)return;const next=room.maintenanceState==='OUT_OF_ORDER'?'AVAILABLE':'OUT_OF_ORDER';const reason=next==='OUT_OF_ORDER'?window.prompt('Reason / defect')||'':'';if(next==='AVAILABLE'||reason.trim())await command('room.condition',{id:room.id,state:next,reason},rec.version)};
 const release=async(block:any)=>{const inspection=window.prompt('Inspection / release note');const rec=recordOf(s,'roomBlocks',block.id);if(inspection?.trim()&&rec)await command('room.unblock',{id:block.id,inspection:inspection.trim()},rec.version)};
 const columns=['DIRTY','CLEANING','INSPECTION','CLEAN'];
 return <div className="h-full overflow-auto bg-slate-950 p-5 text-white">
   <div className="flex flex-wrap items-start justify-between gap-3"><div><h1 className="text-2xl font-bold">Housekeeping</h1><p className="mt-1 text-sm text-slate-400">Room readiness is independent from occupancy. Cleaning state changes are versioned and audited.</p></div><input className={fieldClass+' max-w-xs'} placeholder="Filter room / floor / wing…" value={query} onChange={e=>setQuery(e.target.value)}/></div>
